                                    <!-- YOUTUBE VIDEO IFRAME START-->
                                    <div data-video="https://www.youtube.com/watch?v=39vCTk22w88&ab_channel=MuhammadNorKholit"
                                        id="youtube-audio">
                                    </div>
                                    <script src="{{asset('assets/themes/04')}}/iframe_api"></script>
                                    <script>
                                        var player;
                                        var startSeconds = '';
                                        var endSeconds = '';
                                        function onYouTubeIframeAPIReady() {
                                            var ytplay = document.getElementById("youtube-audio");
                                            ytplay.innerHTML = '<div id="youtube-player"></div>';
                                            ytplay.style.cssText = 'visibility:hidden;';
                                            ytplay.onclick = toggleAudio;
                                            player = new YT.Player('youtube-player', {
                                                height: '20',
                                                width: '20',
                                                videoId: extractVideoID(ytplay.dataset.video),
                                                playerVars: {
                                                    autoplay: ytplay.dataset.autoplay,
                                                    loop: ytplay.dataset.loop,
                                                    start: startSeconds,
                                                    end: endSeconds,
                                                    playsinline: 1

                                                },
                                                events: {
                                                    'onReady': onPlayerReady,
                                                    'onStateChange': onPlayerStateChange
                                                }
                                            });
                                        }
                                        function toggleAudio() {
                                            if (player.getPlayerState() == 1 || player.getPlayerState() == 3) {
                                                player.pauseVideo();
                                            } else {
                                                player.playVideo();
                                            }
                                        }
                                        function onPlayerReady(event) {
                                            event.target.playVideo();
                                            // player.seekTo(startSeconds);
                                            player.setPlaybackQuality("small");
                                        }
                                        function onPlayerStateChange(event) {
                                            if (event.data === 0) {
                                                player.playVideo();
                                                startSeconds: startSeconds;
                                                endSeconds: endSeconds;
                                                var duration = startSeconds - endSeconds;
                                                setTimeout(restartVideoSection, duration * 1000);
                                            }
                                        }
                                        function restartVideoSection() {
                                            player.seekTo(startSeconds);
                                        }
                                        function extractVideoID(url) {
                                            var regExp = /^.*((youtu.be\/)|(v\/)|(\/u\/\w\/)|(embed\/)|(watch\?))\??v?=?([^#\&\?]*).*/;
                                            var match = url.match(regExp);
                                            if (match && match[7].length == 11) {
                                                return match[7];
                                            } else {
                                                console.log('Could not extract video ID.');
                                            }
                                        }
                                    </script>
                                    <!-- YOUTUBE VIDEO IFRAME END-->

